    private static int assertions;
    private static void Check(bool value,string why) {assertions++;if(!value)throw new Exception(why);}
    private static void Reject(Action action,string why) {assertions++;try{action();}catch(ArgumentException){return;}catch(InvalidOperationException){return;}catch(WritePreconditionConflictException){return;}throw new Exception("Expected rejection: "+why);}
    private static JObject Op(string op,string key,string id)=>new(){["op"]=op,[key]=id};
    private static JToken Apply(IPreparedWriteField f,JToken expected,JToken value) {expected=JToken.Parse(expected.ToString(Newtonsoft.Json.Formatting.None));f.Validate(value);if(!JToken.DeepEquals(f.Read(),expected))throw new InvalidOperationException("CAS");f.Write(value);var applied=f is IPreparedStructuralWrite structural?structural.AppliedValue():value;if(!JToken.DeepEquals(f.Read(),applied))throw new Exception("Readback");return applied;}
    private static IReadOnlyList<ResolvedWriteField> ApplyArea(VerseWriteFieldResolver resolver,JObject operation,JObject value,JToken? expected=null) {
        var map=GameWorldReferences.ResolveMap((string?)operation["map"]);var area=AreaZoneReadings.ResolveArea(map,(string?)operation["area"]);operation["value"]=value.DeepClone();operation["expect"]=expected?.DeepClone()??((string?)operation["op"]=="set_area_cell_flags"?AreaCellFlags.Read(area,AreaCellFlags.Coordinates(map,value["cells"]!)):AreaZoneReadings.CellState(area,area.ActiveCells));
        var fields=resolver.ResolveFieldsTest(operation);foreach(var row in fields){row.Field.Validate(row.Value);if(!JToken.DeepEquals(row.Field.Read(),row.Expected))throw new InvalidOperationException("CAS");}foreach(var row in fields){row.Field.Write(row.Value);if(!JToken.DeepEquals(row.Field.Read(),row.Value))throw new Exception("Cell readback");}return fields;
    }
    private static void UndoArea(IReadOnlyList<ResolvedWriteField> fields) {foreach(var row in fields){row.Field.Validate(row.Expected);if(!JToken.DeepEquals(row.Field.Read(),row.Value))throw new InvalidOperationException("Undo CAS");}foreach(var row in fields){row.Field.Write(row.Expected);if(!JToken.DeepEquals(row.Field.Read(),row.Expected))throw new Exception("Cell undo readback");}}
