    public static void Main()
    {
        Current.Game=new Game();var db=PolicyReadings.Database;var basePolicy=db.MakeNewFoodRestriction();var shared=db.MakeNewFoodRestriction();shared.label="Shared";
        var meal=new ThingDef{defName="MealSimple",ingestible=new()};DefDatabase<ThingDef>.AllDefsListForReading.Add(meal);
        var cannibal=new SpecialThingFilterDef{defName="AllowCannibal"};DefDatabase<SpecialThingFilterDef>.AllDefsListForReading.Add(cannibal);shared.filter.SetAllow(meal,true);shared.filter.SetAllow(cannibal,false);
        shared.filter.AllowedHitPointsPercents=new(.35f,.85f);
        var map=new Map();Find.Maps.Add(map);var a=new Pawn("Pawn_A"){Map=map};var world=new Pawn("Pawn_World"){Spawned=false};var temporary=new Pawn("Pawn_Temporary"){Spawned=false};var fallback=new Pawn("Pawn_Default"){Map=map};
        a.foodRestriction.CurrentFoodPolicy=shared;world.foodRestriction.CurrentFoodPolicy=shared;temporary.foodRestriction.CurrentFoodPolicy=shared;
        PawnsFinder.All_AliveOrDead.AddRange(new[]{a,fallback});PawnsFinder.AllMapsWorldAndTemporary_AliveOrDead.Add(temporary);PawnsFinder.AllMapsCaravansAndTravellingTransporters_Alive.Add(world);
        var r=new VerseWriteFieldResolver(new FixtureData());
        Check(PolicyReadings.Users(shared).Count==3,"User coverage must include world, map and temporary holders");
        var reading=PolicyReadings.Read(new JObject());Check((bool)reading["complete"]!,"complete");Check(fallback.foodRestriction.Raw==null,"Reading policies must not lazily assign defaults");
        Check(JToken.DeepEquals(PolicyReadings.AssignedPolicyKey(fallback),PolicyReadings.Key(basePolicy)),"Effective fallback must match native getter");
        var mutant=new Pawn("Mutant"){IsMutant=true};mutant.mutant.Def.disablePolicies=true;Check(PolicyReadings.AssignedPolicyKey(mutant).Type==JTokenType.Null,"Disabled mutant policy is null");mutant.foodRestriction.CurrentFoodPolicy=shared;PawnsFinder.AllMapsWorldAndTemporary_AliveOrDead.Add(mutant);Check(PolicyReadings.Users(shared).Values<string>().Contains(mutant.Id),"Disabled native policy references remain covered for impact and deletion");
        var agarilux=new ThingDef{defName="Agarilux",Nutrition=0.3f};var latent=new ThingDef{defName="LatentNoNutrition",Nutrition=0};var retainedMod=new ThingDef{defName="RetainedMod",Official=false,Nutrition=0};DefDatabase<ThingDef>.AllDefsListForReading.AddRange(new[]{agarilux,latent,retainedMod});shared.filter.SetAllow(agarilux,true);shared.filter.SetAllow(latent,true);shared.filter.SetAllow(retainedMod,true);
        var stableId=PolicyReadings.Id(shared);var nativeBeforeRename=shared.GetUniqueLoadID();var keyBeforeRename=PolicyReadings.Key(shared);var idsBeforeRename=PolicyReadings.Structure();
